window.RP_SESSION={"id":"S-8e50c02521ce","messages":[{"id":"RP-0197005","time":"2026-07-20T02:33:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아! 나의 이야기를 듣고 싶어서 지금 이 방에 갸웃 거리고 있구려! 반갑소. 그대의 행색을 보아하니 그대는 필시 내가 여태까지 겪여온 낭만이 가득하고, 교훈이 있고, 때로는 눈물이 넘치는 여행담을 듣고 싶어 하는 것이 분명 해 보이니 내 그대에게 모든것을 설명 해 주도록 하겠소! 우선 그 전에 나의 이름을 설명 하는 것이 옳을 터. 나의 이름은 돈 뻬르난떼 데 일리아인데, 여기서 돈 뻬르난떼는 내가 뻬르난떼경 이라는 뜻을 가지고 있는 단어이며, 데 일리아는 내가 일리아에서 왔다는 뜻이오. 물론 일리아는 대륙이오나, 나와 같은 위대한 편력기사들을 담을 만한 그릇은 이와 같은 대륙밖에 없기에 나의 이름과 또 나의 무게는 필히 내가 대륙에서 출신했음을 뜻하는 것일 것이오! 그리고 나의 출신 가문은 루밍루꼬인데 루밍루꼬가 무엇을 하는 가문이나 라고 말한다면 골기아에 있는 다른 가문들과는 달리 욕심을 부리지도, 그렇다고 해서 농민들을 수탈하지도, 다른 귀족 가문들에게 불명예스러운 행동을 하","characters":["P-1a1afae9c8db"]},{"id":"RP-0197006","time":"2026-07-20T02:33:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"잠깐! 어딜 가시오! 아직 이야기가 더 남았소! 내 모험담은 아직 끝나질 않았거늘!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0197007","time":"2026-07-20T02:33:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-1a1afae9c8db"]},{"id":"RP-0197008","time":"2026-07-20T02:33:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
